import os, pty, subprocess, time, select, signal, termios, fcntl, struct, sys, re

def capture(args, rows=24, cols=80, dur=0.35, send=b'q', envextra=None):
    master, slave=pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols,0,0))
    env=os.environ.copy(); env['TERM']='xterm'
    if envextra: env.update(envextra)
    p=subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, env=env, close_fds=True)
    os.close(slave)
    out=b''; start=time.time(); sent=False
    while time.time()-start<dur+1:
        r,_,_=select.select([master],[],[],0.02)
        if r:
            try: data=os.read(master,8192)
            except OSError: break
            if not data: break
            out+=data
        if send and not sent and time.time()-start>dur:
            try: os.write(master,send)
            except OSError: pass
            sent=True
        if p.poll() is not None:
            for _ in range(10):
                r,_,_=select.select([master],[],[],0.02)
                if r:
                    try: out+=os.read(master,8192)
                    except OSError: break
                else: break
            break
    if p.poll() is None:
        p.terminate()
        try:p.wait(timeout=1)
        except subprocess.TimeoutExpired:p.kill();p.wait()
    try: os.close(master)
    except: pass
    return out, p.returncode

class Term:
    def __init__(self, rows=24, cols=80):
        self.rows=rows; self.cols=cols; self.r=0; self.c=0; self.fg=None; self.bg=None; self.bold=False
        self.grid=[[{'ch':' ','fg':None,'bg':None,'bold':False} for c in range(cols)] for r in range(rows)]
    def clear(self):
        self.grid=[[{'ch':' ','fg':None,'bg':None,'bold':False} for c in range(self.cols)] for r in range(self.rows)]
    def put(self,ch):
        if ch=='\n': self.r=min(self.rows-1,self.r+1); return
        if ch=='\r': self.c=0; return
        if ch=='\b': self.c=max(0,self.c-1); return
        if 0<=self.r<self.rows and 0<=self.c<self.cols:
            self.grid[self.r][self.c]={'ch':ch,'fg':self.fg,'bg':self.bg,'bold':self.bold}
        self.c+=1
        if self.c>=self.cols: self.c=self.cols-1
    def csi(self, params, final):
        private=False
        if params.startswith('?'):
            private=True; params=params[1:]
        if final in 'Hf':
            ps=[int(x) if x else 1 for x in params.split(';')] if params else [1,1]
            row=ps[0] if len(ps)>=1 else 1; col=ps[1] if len(ps)>=2 else 1
            self.r=max(0,min(self.rows-1,row-1)); self.c=max(0,min(self.cols-1,col-1))
        elif final=='d':
            row=int(params or '1'); self.r=max(0,min(self.rows-1,row-1))
        elif final=='G':
            col=int(params or '1'); self.c=max(0,min(self.cols-1,col-1))
        elif final=='J':
            if params in ('2',''):
                self.clear()
        elif final=='m':
            ps=[0] if params=='' else [int(x) if x else 0 for x in params.split(';')]
            for p in ps:
                if p==0:
                    self.fg=None; self.bg=None; self.bold=False
                elif p==1: self.bold=True
                elif p==22: self.bold=False
                elif p==39: self.fg=None
                elif p==49: self.bg=None
                elif 30<=p<=37: self.fg=p-30
                elif 40<=p<=47: self.bg=p-40
                elif 90<=p<=97: self.fg=p-90+8
                elif 100<=p<=107: self.bg=p-100+8
    def parse(self,data):
        s=data.decode('utf-8','replace'); i=0
        while i<len(s):
            ch=s[i]
            if ch=='\x1b':
                i+=1
                if i>=len(s): break
                if s[i]=='[':
                    i+=1; start=i
                    while i<len(s) and not ('@'<=s[i]<='~'):
                        i+=1
                    if i<len(s):
                        params=s[start:i]; final=s[i]; self.csi(params,final); i+=1
                elif s[i] in '()':
                    i+=2
                else:
                    i+=1
            elif ch in '\x0f\x0e':
                i+=1
            else:
                self.put(ch); i+=1

def render(term, attrs=False):
    lines=[]
    for row in term.grid:
        line=''
        for cell in row:
            if cell['bg'] is not None and cell['ch']==' ':
                line+='█'
            elif cell['ch']==' ':
                line+='·' if attrs else ' '
            else:
                line+=cell['ch']
        lines.append(line.rstrip())
    return '\n'.join(f'{i+1:02d}:{ln}' for i,ln in enumerate(lines) if ln.strip())

if __name__=='__main__':
    sep=' -- '
    tests=sys.argv[1:]
    if not tests: tests=['']
    for t in tests:
        args=['./executable']+([x for x in t.split() if x] if t else [])
        out,code=capture(args)
        term=Term(); term.parse(out)
        print('ARGS',args,'code',code,'bytes',len(out))
        print(render(term))
        print('--- raw head ---')
        print(out[:500].decode('utf-8','replace').replace('\x1b','^[',).replace('\r','^M'))
        print('====')
