#!/usr/bin/env python3
"""Original reimplementation of the tty-clock command-line clock."""
import os
import sys
import time
import stat as statmod
import curses

USAGE = (
"usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] \n"
"    -s            Show seconds                                   \n"
"    -S            Screensaver mode                               \n"
"    -x            Show box                                       \n"
"    -c            Set the clock at the center of the terminal    \n"
"    -C [0-7]      Set the clock color                            \n"
"    -b            Use bold colors                                \n"
"    -t            Set the hour in 12h format                     \n"
"    -u            Use UTC time                                   \n"
"    -T tty        Display the clock on the specified terminal    \n"
"    -r            Do rebound the clock                           \n"
"    -f format     Set the date format                            \n"
"    -n            Don't quit on keypress                         \n"
"    -v            Show tty-clock version                         \n"
"    -i            Show some info about tty-clock                 \n"
"    -h            Show this page                                 \n"
"    -D            Hide date                                      \n"
"    -B            Enable blinking colon                          \n"
"    -d delay      Set the delay between two redraws of the clock. Default 1s. \n"
"    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n"
)

VERSION = "TTY-Clock 2 © devel version\n"
INFO = "TTY-Clock 2 © by Martin Duquesnoy (xorg62@gmail.com), Grey (grey@greytheory.net)\n"

# 5x6 seven-segment style digits.  A true cell is rendered as a colored space.
DIGITS = {
    '0': ["111111", "110011", "110011", "110011", "111111"],
    '1': ["000011", "000011", "000011", "000011", "000011"],
    '2': ["111111", "000011", "111111", "110000", "111111"],
    '3': ["111111", "000011", "111111", "000011", "111111"],
    '4': ["110011", "110011", "111111", "000011", "000011"],
    '5': ["111111", "110000", "111111", "000011", "111111"],
    '6': ["111111", "110000", "111111", "110011", "111111"],
    '7': ["111111", "000011", "000011", "000011", "000011"],
    '8': ["111111", "110011", "111111", "110011", "111111"],
    '9': ["111111", "110011", "111111", "000011", "111111"],
}

FG_BASE = 1
BG_BASE = 9
DEFAULT_COLOR = 2

class Config:
    def __init__(self):
        self.show_seconds = False
        self.screensaver = False
        self.box = False
        self.center = False
        self.color = DEFAULT_COLOR
        self.bold = False
        self.hour12 = False
        self.utc = False
        self.rebound = False
        self.date_format = "%F"
        self.noquit = False
        self.show_date = True
        self.blink_colon = False
        self.delay_sec = 1
        self.delay_nsec = 0
        self.tty = None
        self.x = 0
        self.y = 0
        self.dx = 1
        self.dy = 1
        self._initial_rebound_shift = False


def c_atoi(value):
    """Parse like C atoi: leading whitespace, optional sign, decimal prefix."""
    if value is None:
        return 0
    s = str(value)
    i = 0
    n = len(s)
    while i < n and s[i] in ' \t\n\r\v\f':
        i += 1
    sign = 1
    if i < n and s[i] in '+-':
        if s[i] == '-':
            sign = -1
        i += 1
    val = 0
    any_digit = False
    while i < n and '0' <= s[i] <= '9':
        any_digit = True
        val = val * 10 + (ord(s[i]) - 48)
        i += 1
    if not any_digit:
        return 0
    return sign * val


def print_getopt_error(prog, kind, opt):
    if kind == 'missing':
        sys.stderr.write(f"{prog}: option requires an argument -- '{opt}'\n")
    else:
        sys.stderr.write(f"{prog}: invalid option -- '{opt}'\n")


def validate_tty(path, cfg):
    try:
        st = os.stat(path)
    except OSError as e:
        sys.stderr.write(f"tty-clock: error: couldn't stat '{path}': {e.strerror}.\n")
        raise SystemExit(1)
    if not statmod.S_ISCHR(st.st_mode):
        sys.stderr.write(f"tty-clock: error: '{path}' doesn't appear to be a character device.\n")
        raise SystemExit(1)
    cfg.tty = path


def handle_option(opt, arg, cfg):
    if opt == 'h':
        sys.stdout.write(USAGE)
        raise SystemExit(0)
    if opt == 'v':
        sys.stdout.write(VERSION)
        raise SystemExit(0)
    if opt == 'i':
        sys.stdout.write(INFO)
        raise SystemExit(0)
    if opt == 's':
        cfg.show_seconds = True
    elif opt == 'S':
        cfg.screensaver = True
    elif opt == 'x':
        cfg.box = True
    elif opt == 'c':
        cfg.center = True
    elif opt == 'C':
        val = c_atoi(arg)
        cfg.color = val if 0 <= val <= 7 else DEFAULT_COLOR
    elif opt == 'b':
        cfg.bold = True
    elif opt == 't':
        cfg.hour12 = True
    elif opt == 'u':
        cfg.utc = True
    elif opt == 'T':
        validate_tty(arg, cfg)
    elif opt == 'r':
        cfg.rebound = True
        cfg._initial_rebound_shift = True
    elif opt == 'f':
        cfg.date_format = arg
    elif opt == 'n':
        cfg.noquit = True
    elif opt == 'D':
        cfg.show_date = False
    elif opt == 'B':
        cfg.blink_colon = True
    elif opt == 'd':
        cfg.delay_sec = c_atoi(arg)
    elif opt == 'a':
        cfg.delay_nsec = c_atoi(arg)


def parse_args(argv):
    cfg = Config()
    prog = sys.argv[0] if sys.argv else './executable'
    flags = set('iuvsScbtrahDBxn')
    need_arg = set('CfTda')
    valid = flags | need_arg
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == '--':
            break
        if arg == '-' or not arg.startswith('-') or len(arg) < 2:
            i += 1
            continue
        j = 1
        while j < len(arg):
            opt = arg[j]
            if opt not in valid:
                print_getopt_error(prog, 'invalid', opt)
                sys.stdout.write(USAGE)
                raise SystemExit(0)
            if opt in need_arg:
                if j + 1 < len(arg):
                    val = arg[j+1:]
                else:
                    i += 1
                    if i >= len(argv):
                        print_getopt_error(prog, 'missing', opt)
                        sys.stdout.write(USAGE)
                        raise SystemExit(0)
                    val = argv[i]
                handle_option(opt, val, cfg)
                break
            else:
                handle_option(opt, None, cfg)
                j += 1
        i += 1
    return cfg


def redirect_tty_if_needed(cfg):
    if not cfg.tty:
        return
    try:
        fd = os.open(cfg.tty, os.O_RDWR | getattr(os, 'O_NOCTTY', 0))
    except OSError as e:
        sys.stderr.write(f"tty-clock: error: couldn't open '{cfg.tty}': {e.strerror}.\n")
        raise SystemExit(1)
    os.dup2(fd, 1)
    os.dup2(fd, 2)
    if fd > 2:
        os.close(fd)


def clock_width(cfg):
    return 54 if cfg.show_seconds else 35


def clock_height(cfg):
    if cfg.box and cfg.show_date:
        return 9
    if cfg.show_date:
        return 8
    return 7


def get_tm(cfg):
    now = time.time()
    return time.gmtime(now) if cfg.utc else time.localtime(now)


def format_time_and_date(cfg, tm):
    hour = tm.tm_hour
    if cfg.hour12:
        h = hour % 12
        if h == 0:
            h = 12
        timestr = f"{h:02d}{tm.tm_min:02d}"
    else:
        timestr = f"{hour:02d}{tm.tm_min:02d}"
    if cfg.show_seconds:
        timestr += f"{tm.tm_sec:02d}"
    try:
        date = time.strftime(cfg.date_format, tm)
    except Exception:
        date = ''
    if cfg.hour12:
        date += " [AM]" if hour < 12 else " [PM]"
    return timestr, date


def safe_addstr(stdscr, y, x, text, attr=0):
    if not text:
        return
    rows, cols = stdscr.getmaxyx()
    if y < 0 or y >= rows or x >= cols:
        return
    # For negative x, mimic ncurses mvaddstr failure rather than clipping most UI elements.
    if x < 0:
        return
    if x + len(text) > cols:
        text = text[:max(0, cols - x)]
    if not text:
        return
    try:
        stdscr.addstr(y, x, text, attr)
    except curses.error:
        pass


def safe_addch(stdscr, y, x, ch, attr=0):
    rows, cols = stdscr.getmaxyx()
    if y < 0 or y >= rows or x < 0 or x >= cols:
        return
    try:
        stdscr.addch(y, x, ch, attr)
    except curses.error:
        pass


def safe_hline(stdscr, y, x, ch, n, attr=0):
    rows, cols = stdscr.getmaxyx()
    if n <= 0 or y < 0 or y >= rows or x >= cols:
        return
    if x < 0:
        return
    n = min(n, cols - x)
    if n <= 0:
        return
    try:
        stdscr.hline(y, x, ch, n, attr)
    except curses.error:
        # Some minimal terminals do not support ACS hline; fall back to repeated chars.
        for i in range(n):
            safe_addch(stdscr, y, x+i, ch, attr)


def fg_attr(color, bold=False):
    attr = curses.color_pair(FG_BASE + color) if curses.has_colors() else 0
    if bold:
        attr |= curses.A_BOLD
    return attr


def bg_attr(color, blink=False):
    attr = curses.color_pair(BG_BASE + color) if curses.has_colors() else 0
    if blink:
        attr |= curses.A_BLINK
    return attr


def draw_box(stdscr, y, x, w, h):
    if w < 2 or h < 2:
        return
    safe_addch(stdscr, y, x, curses.ACS_ULCORNER)
    safe_hline(stdscr, y, x+1, curses.ACS_HLINE, w-2)
    safe_addch(stdscr, y, x+w-1, curses.ACS_URCORNER)
    for yy in range(y+1, y+h-1):
        safe_addch(stdscr, yy, x, curses.ACS_VLINE)
        safe_addch(stdscr, yy, x+w-1, curses.ACS_VLINE)
    safe_addch(stdscr, y+h-1, x, curses.ACS_LLCORNER)
    safe_hline(stdscr, y+h-1, x+1, curses.ACS_HLINE, w-2)
    safe_addch(stdscr, y+h-1, x+w-1, curses.ACS_LRCORNER)


def draw_digit(stdscr, y, x, digit, attr_on):
    pat = DIGITS.get(digit, DIGITS['0'])
    for r, line in enumerate(pat):
        # Draw runs; blank cells are left as erased background.
        c = 0
        while c < 6:
            if line[c] == '1':
                start = c
                while c < 6 and line[c] == '1':
                    c += 1
                safe_addstr(stdscr, y+r, x+start, ' ' * (c-start), attr_on)
            else:
                c += 1


def draw_colon(stdscr, y, x, cfg, tm, attr_on):
    visible = True
    if cfg.blink_colon:
        visible = (tm.tm_sec % 2) == 1
    if visible:
        attr = attr_on
    else:
        attr = fg_attr(cfg.color, False)
    for r in (1, 3):
        safe_addstr(stdscr, y+r, x, '  ', attr)


def draw_clock(stdscr, cfg):
    rows, cols = stdscr.getmaxyx()
    w = clock_width(cfg)
    h = clock_height(cfg)

    if cfg._initial_rebound_shift and not cfg.center:
        cfg.x += 2
        cfg.y += 2
        cfg._initial_rebound_shift = False

    if cfg.center:
        # Match the integer arithmetic of the original: LINES/2 - height/2.
        x = cols // 2 - w // 2
        y = rows // 2 - 7 // 2
    else:
        max_x = max(0, cols - w)
        max_y = max(0, rows - h)
        cfg.x = max(0, min(cfg.x, max_x))
        cfg.y = max(0, min(cfg.y, max_y))
        x, y = cfg.x, cfg.y

    tm = get_tm(cfg)
    timestr, datestr = format_time_and_date(cfg, tm)

    stdscr.erase()

    if cfg.box:
        draw_box(stdscr, y, x, w, 7)

    on_attr = bg_attr(cfg.color, cfg.bold)
    digit_y = y + 1
    rel = [1, 8, 20, 27]
    colons = [16]
    if cfg.show_seconds:
        rel = [1, 8, 20, 27, 39, 46]
        colons = [16, 35]

    for idx, ch in enumerate(timestr):
        if idx < len(rel):
            draw_digit(stdscr, digit_y, x + rel[idx], ch, on_attr)
    for cx in colons:
        draw_colon(stdscr, digit_y, x + cx, cfg, tm, on_attr)

    if cfg.show_date:
        date_attr = fg_attr(cfg.color, cfg.bold)
        if cfg.box:
            date_w = len(datestr) + 2
            date_x = x + (w - date_w) // 2
            date_y = y + 6
            if date_x >= 0 and date_w >= 2:
                # Overlay the small date box on the clock's bottom border.
                safe_addch(stdscr, date_y, date_x, curses.ACS_ULCORNER)
                safe_hline(stdscr, date_y, date_x + 1, curses.ACS_HLINE, date_w - 2)
                safe_addch(stdscr, date_y, date_x + date_w - 1, curses.ACS_URCORNER)
                safe_addch(stdscr, date_y + 1, date_x, curses.ACS_VLINE)
                safe_addch(stdscr, date_y + 1, date_x + date_w - 1, curses.ACS_VLINE)
                safe_addch(stdscr, date_y + 2, date_x, curses.ACS_LLCORNER)
                safe_hline(stdscr, date_y + 2, date_x + 1, curses.ACS_HLINE, date_w - 2)
                safe_addch(stdscr, date_y + 2, date_x + date_w - 1, curses.ACS_LRCORNER)
                safe_addstr(stdscr, date_y + 1, date_x + 1, datestr, date_attr)
        else:
            date_x = x + (w - len(datestr)) // 2
            if date_x >= 0:
                safe_addstr(stdscr, y + 7, date_x, datestr, date_attr)

    stdscr.refresh()


def move_rebound(cfg, stdscr):
    if cfg.center or not cfg.rebound:
        return
    rows, cols = stdscr.getmaxyx()
    w = clock_width(cfg)
    h = clock_height(cfg)
    max_x = max(0, cols - w)
    max_y = max(0, rows - h)
    nx = cfg.x + cfg.dx
    ny = cfg.y + cfg.dy
    if nx < 0 or nx > max_x:
        cfg.dx = -cfg.dx
        nx = cfg.x + cfg.dx
    if ny < 0 or ny > max_y:
        cfg.dy = -cfg.dy
        ny = cfg.y + cfg.dy
    cfg.x = max(0, min(nx, max_x))
    cfg.y = max(0, min(ny, max_y))


def handle_key(ch, cfg, stdscr):
    if ch < 0:
        return False, False
    # Screensaver mode exits on any key unless -n was supplied.
    if cfg.screensaver and not cfg.noquit:
        return True, False
    try:
        c = chr(ch & 0xff)
    except ValueError:
        return False, False
    lc = c.lower()
    changed = False
    if lc == 'q':
        if not cfg.noquit:
            return True, False
    elif lc == 's':
        cfg.show_seconds = not cfg.show_seconds
        changed = True
    elif lc == 'x':
        cfg.box = not cfg.box
        changed = True
    elif lc == 'c':
        cfg.center = not cfg.center
        changed = True
    elif lc == 't':
        cfg.hour12 = not cfg.hour12
        changed = True
    elif lc == 'b':
        cfg.bold = not cfg.bold
        changed = True
    elif lc == 'r':
        cfg.rebound = True
        cfg._initial_rebound_shift = True
        changed = True
    elif c in '01234567':
        cfg.color = ord(c) - 48
        changed = True
    elif not cfg.center:
        rows, cols = stdscr.getmaxyx()
        max_x = max(0, cols - clock_width(cfg))
        max_y = max(0, rows - clock_height(cfg))
        if lc == 'h':
            cfg.x = max(0, cfg.x - 1); changed = True
        elif lc == 'l':
            cfg.x = min(max_x, cfg.x + 1); changed = True
        elif lc == 'k':
            cfg.y = max(0, cfg.y - 1); changed = True
        elif lc == 'j':
            cfg.y = min(max_y, cfg.y + 1); changed = True
    return False, changed


def setup_colors():
    try:
        curses.start_color()
        curses.use_default_colors()
    except curses.error:
        return
    if not curses.has_colors():
        return
    colors = [
        curses.COLOR_BLACK,
        curses.COLOR_RED,
        curses.COLOR_GREEN,
        curses.COLOR_YELLOW,
        curses.COLOR_BLUE,
        curses.COLOR_MAGENTA,
        curses.COLOR_CYAN,
        curses.COLOR_WHITE,
    ]
    for i, col in enumerate(colors):
        try:
            curses.init_pair(FG_BASE + i, col, -1)
            curses.init_pair(BG_BASE + i, -1, col)
        except curses.error:
            pass


def run_curses(cfg):
    try:
        stdscr = curses.initscr()
    except curses.error:
        term = os.environ.get('TERM') or 'unknown'
        sys.stderr.write(f"Error opening terminal: {term}.\n")
        return 1
    try:
        try:
            curses.noecho()
            curses.cbreak()
        except curses.error:
            pass
        try:
            stdscr.keypad(True)
        except curses.error:
            pass
        setup_colors()
        try:
            curses.curs_set(0)
        except curses.error:
            pass
        try:
            stdscr.nodelay(True)
        except curses.error:
            pass

        # The original clears the alternate screen before its first paint.
        try:
            stdscr.clear()
            stdscr.refresh()
        except curses.error:
            pass

        running = True
        while running:
            draw_clock(stdscr, cfg)
            total_delay = cfg.delay_sec + cfg.delay_nsec / 1000000000.0
            if total_delay < 0:
                total_delay = 0
            deadline = time.monotonic() + total_delay
            changed = False
            while True:
                try:
                    ch = stdscr.getch()
                except curses.error:
                    ch = -1
                if ch != -1:
                    quit_now, changed = handle_key(ch, cfg, stdscr)
                    if quit_now:
                        running = False
                        break
                    if changed:
                        break
                if total_delay == 0:
                    break
                now = time.monotonic()
                if now >= deadline:
                    break
                time.sleep(min(0.02, max(0, deadline - now)))
            if not running:
                break
            if not changed:
                move_rebound(cfg, stdscr)
        return 0
    finally:
        try:
            curses.endwin()
        except curses.error:
            pass


def main():
    try:
        cfg = parse_args(sys.argv[1:])
        redirect_tty_if_needed(cfg)
        code = run_curses(cfg)
    except SystemExit as e:
        raise
    except BrokenPipeError:
        code = 1
    return code

if __name__ == '__main__':
    sys.exit(main())
